(() => {
const teams=window.HBSTV_TEAMS||[],esc=escapeHtml;
const norm=s=>normalizeText(String(s)).replace(/[^a-z0-9]/g,'');
const nickAliases={tab:'tabsenn',tabsen:'tabsenn',conjure:'c0njure',hard:'hardzera',betao:'insani',valk:'valknut',ryota:'ry0ta',misiuta:'misuuta',misuta:'misuuta',marvwyn:'marvywn',marvyw:'marvywn',...(window.HBSTV_PLAYER_INDEX?.aliases||{})};
const nickKey=s=>norm(nickAliases[norm(s)]||s).replace(/0/g,'o');
const hof=name=>players.find(p=>nickKey(p.name)===nickKey(name));
const allPlayers=new Map();for(const p of players)allPlayers.set(nickKey(p.name),{id:nickKey(p.name),name:p.name,teams:[],hof:p});for(const t of teams)for(const m of t.members){const id=nickKey(m.name);if(!allPlayers.has(id))allPlayers.set(id,{id,name:m.name,teams:[],hof:hof(m.name)});allPlayers.get(id).teams.push(t);}
window.registerSearchPlayers=names=>{for(const name of names){const id=nickKey(name);if(!allPlayers.has(id))allPlayers.set(id,{id,name,teams:[],hof:hof(name)});}};
window.registerSearchPlayers(Object.values(window.RANKS_PLAYER_RANKINGS||{}).flat().map(p=>p.name));
for(const r of window.HBSTV_PLAYER_INDEX?.players||[]){window.registerSearchPlayers([r.name]);const p=allPlayers.get(nickKey(r.name));p.searchText=[...r.aliases,...r.realNames].join(' ');p.generic=r;if(!p.hof)p.teams=r.teams.map(t=>teams.find(x=>x.id===t.id)).filter(Boolean);}
const findTeam=(name,year)=>{if(/^(gt|legendaryteam)$/.test(norm(name)))return year?teams.find(t=>t.id==='gt'+year):null;return teams.find(t=>[t.name,...t.aliases,...(t.searchAliases||[])].some(a=>norm(a)===norm(name)));};
window.getTeamProfileHref=(name,year)=>{const t=findTeam(name,year);return t?'#time/'+t.id:'#times';};
function oneLogo(logo,name,size=''){if(!logo)return `<span class="club-logo club-initials ${size}" aria-label="${esc(name)}">${esc(name.slice(0,2))}</span>`;const c=logo.crop;return `<span class="club-logo ${size}"><img src="${esc(logo.src)}" alt="Logo ${esc(name)}" style="width:${100/c.w}%;height:${100/c.h}%;left:${-100*c.x/c.w}%;top:${-100*c.y/c.h}%"></span>`;}
function logo(t,size=''){return `<span class="club-logos">${oneLogo(t.logo,t.name,size)}${t.extraLogo?oneLogo(t.extraLogo,'Goblins Cheating',size):''}</span>`;}
const screen=document.createElement('section');screen.id='team-profile-screen';screen.hidden=true;document.querySelector('.content').append(screen);
let clubYear='',memberQuery='',directoryQuery='';
const niceTitle=s=>s.replace(/\s*\[TIER[^\]]*\]/gi,'').replace(/\s*\|\s*/g,' | ').replace(/^(GSC|GSE|LCB|PNL|WHL|ESC|TSL|SUVOH|ACE|MAWARE|RANK S|GZ)\s+(?!\|)(.+)$/i,'$1 | $2');
function tournament(r){return `<button class="club-title ${r.major?'club-major':''}" data-club-tournament="${esc(r.id)}">${window.renderOrganizationEmblem?.(niceTitle(r.title))||'<span aria-hidden="true">♜</span>'}<strong>${esc(niceTitle(r.title))}</strong><span>${r.year}</span>${r.major?'<b>MAJOR</b>':'<i>↗</i>'}</button>`;}
function memberCard(m){const p=hof(m.name);return `<button class="club-member" data-entity-player="${esc(m.id)}"><span class="club-member-initial">${esc(m.name.slice(0,2))}</span><strong>${esc(window.HBSTV.name(m.name))}</strong><small>${m.years.join(' · ')}</small><span class="club-member-label">${p?'Hall of Fame ↗':'Ver histórico ↗'}</span></button>`;}
function renderClub(t){const years=[...new Set([...t.titles.map(r=>r.year),...t.members.flatMap(m=>m.years),...t.rankings.map(r=>r.year)])].sort((a,b)=>b-a);const titles=t.titles.filter(r=>!clubYear||r.year===+clubYear),members=t.members.filter(m=>(!clubYear||m.years.includes(+clubYear))&&norm(m.name).includes(norm(memberQuery)));screen.dataset.teamId=t.id;screen.innerHTML=`<div class="club-breadcrumb"><a href="#times">← Todas as equipes</a><span>HISTÓRICO COMPETITIVO</span></div><header class="club-header">${logo(t,'club-logo-large')}<div><span class="eyebrow">HBSTV · PERFIL DE EQUIPE</span><h2>${esc(t.name)}</h2><p>${years.length?(Math.min(...years)===Math.max(...years)?String(years[0]):Math.min(...years)+' — '+Math.max(...years)):'Histórico registrado'} · ${t.aliases.length>1?'Tags registradas: '+esc([...new Set(t.aliases)].join(' / ')):'Block Strike competitivo'}</p></div></header><div class="club-metrics"><div><b>${t.titles.length}</b><span>Títulos documentados</span></div><div><b>${t.titles.filter(r=>r.major).length}</b><span>Majors</span></div><div><b>${t.members.length}</b><span>Jogadores registrados</span></div></div><nav class="club-tabs" aria-label="Seções da equipe"><a href="#club-titles" data-club-anchor="club-titles">Conquistas</a><a href="#club-players" data-club-anchor="club-players">Jogadores</a><a href="#club-history" data-club-anchor="club-history">Histórico anual</a></nav><div class="club-filter"><label>Temporada<select id="club-year"><option value="">Todo o histórico</option>${years.map(y=>`<option ${clubYear===String(y)?'selected':''}>${y}</option>`).join('')}</select></label><p>Elencos históricos reunidos a partir dos campeonatos e fichas anuais cadastrados.</p></div><section id="club-titles"><div class="club-section-head"><h3>Galeria de conquistas</h3><span>${titles.length} TÍTULOS</span></div><div class="club-title-list">${titles.map(tournament).join('')||'<p class="entity-empty">Não há títulos cadastrados para esta temporada.</p>'}</div></section><section id="club-players"><div class="club-section-head"><h3>Jogadores que passaram pela equipe</h3><span>${members.length} REGISTRADOS</span></div><input id="club-member-search" class="entity-field" type="search" placeholder="Filtrar jogador…" aria-label="Filtrar jogadores da equipe" value="${esc(memberQuery)}"><div class="club-members">${members.map(memberCard).join('')||'<p class="entity-empty">Nenhum jogador encontrado neste filtro.</p>'}</div></section><section id="club-history"><div class="club-section-head"><h3>Linha do tempo</h3></div><div class="club-timeline">${years.filter(y=>!clubYear||String(y)===clubYear).map(y=>{const rs=t.rankings.filter(r=>r.year===y),ms=t.members.filter(m=>m.years.includes(y));return `<article><b>${y}</b><div><strong>${t.titles.filter(r=>r.year===y).length} títulos documentados${rs.length?' · Top '+Math.min(...rs.map(r=>r.rank))+' do ano':''}</strong><p>${esc(ms.map(m=>m.name).join(' · ')||'Escalação não informada nos registros disponíveis.')}</p></div></article>`;}).join('')}</div></section><p class="club-source-note">O histórico cobre os registros disponíveis no site. As listas de jogadores não indicam contratos, datas de entrada ou saída, nem um elenco atual. Clique em uma conquista para conferir o campeonato e sua escalação registrada.</p>`;}
function directory(){const term = norm(directoryQuery);
  const entries = teams.flatMap(team => {
    if (team.id !== 'gc2019') return [team];
    return [
      {...team, name: 'TSY 2019', aliases: ['Temp Stormy', 'TSY'], searchAliases: [],
        extraLogo: null, sharedHistory: true},
      {...team, name: 'GC 2019', aliases: ['Goblins Cheating', 'GC'], searchAliases: [],
        logo: team.extraLogo, extraLogo: null, sharedHistory: true}
    ];
  });
  const list = entries.filter(team =>
    norm([team.name, ...team.aliases, ...(team.searchAliases || []),
      ...team.members.map(member => member.name)].join(' ')).includes(term));screen.innerHTML=`<div class="club-directory-heading"><span class="eyebrow">HBSTV · BASE HISTÓRICA</span><h2>Equipes</h2><p>Conquistas, elencos e temporadas do competitivo.</p></div><label class="entity-field-label">Buscar equipe ou jogador<input class="entity-field" id="club-directory-search" type="search" value="${esc(directoryQuery)}" placeholder="Nome do time, tag ou jogador…"></label><div class="club-section-head"><h3>Equipes registradas</h3><span>${list.length} REGISTROS</span></div><div class="club-directory">${list.map(t=>`<a href="#time/${t.id}" class="club-directory-card">${logo(t)}<div><strong>${esc(t.name)}</strong><small>${t.sharedHistory ? 'Histórico compartilhado' : t.titles.length + ' títulos · ' + t.members.length + ' jogadores'}</small></div><span>↗</span></a>`).join('')||'<p class="entity-empty">Nenhuma equipe corresponde à busca.</p>'}</div>`;}
let previousId='';window.renderTeamProfileRoute=()=>{const hash=location.hash;screen.hidden=true;if(hash==='#time/tempstormygoblinscheating'){location.replace('#time/gc2019');return true;}if(hash==='#time/raz3r'){location.replace('#time/razer');return true;}if(hash==='#time/legendaryteam'){directoryQuery='GT';directory();screen.hidden=false;document.title='GT 2021 e GT 2023 — HBSTV.ORG';return true;}if(hash==='#times'){directory();screen.hidden=false;document.title='Equipes — HBSTV.ORG';return true;}if(!hash.startsWith('#time/'))return false;const t=teams.find(t=>t.id===hash.slice(6));if(!t){screen.innerHTML='<div class="entity-empty">Equipe não encontrada. <a href="#times">Ver todas as equipes</a></div>';screen.hidden=false;return true;}if(previousId!==t.id){clubYear='';memberQuery='';previousId=t.id;}renderClub(t);screen.hidden=false;document.title=t.name+' — HBSTV.ORG';return true;};
function showPlayer(id){id=nickKey(id);const p=allPlayers.get(id);if(!p)return;if(p.hof){window.showPlayerProfile(p.hof);return;}if(window.showRegisteredPlayerProfile?.(id))return;document.querySelector('#detail').classList.remove('profile-dialog','image-dialog');const titles=p.teams.flatMap(t=>t.titles.filter(r=>r.roster.some(n=>nickKey(n)===id)).map(r=>({...r,team:t.name})));showDetail(`<span class="eyebrow">HBSTV · JOGADOR REGISTRADO</span><h2>${esc(p.name)}</h2><p>Participações registradas nas escalações e fichas históricas.</p><h3>Equipes no histórico</h3><div class="entity-player-teams">${p.teams.map(t=>`<a href="#time/${t.id}" data-entity-close>${logo(t)}<span>${esc(t.name)}</span><small>${t.members.find(m=>m.id===id).years.join(' · ')}</small></a>`).join('')}</div><h3>Conquistas com escalação registrada</h3>${titles.length?`<ul class="entity-player-titles">${titles.map(r=>`<li>${r.year} · ${esc(niceTitle(r.title))}<small>${esc(r.team)}</small></li>`).join('')}</ul>`:'<p>Os registros disponíveis citam o jogador na equipe, sem escalação individual por título.</p>'}`);}
const oldSearch=document.querySelector('.search'),searchContainer=document.createElement('div');searchContainer.className=oldSearch.className;searchContainer.setAttribute('role','search');while(oldSearch.firstChild)searchContainer.append(oldSearch.firstChild);oldSearch.replaceWith(searchContainer);
const input=document.querySelector('#search'),box=document.createElement('div');box.className='entity-suggestions';box.id='entity-suggestions';box.hidden=true;input.closest('.search').append(box);input.placeholder='Buscar jogador ou time…';input.setAttribute('aria-label','Buscar jogador ou time');input.setAttribute('aria-expanded','false');input.setAttribute('aria-controls',box.id);input.autocomplete='off';let active=-1;
function closeSearch(){box.hidden=true;input.setAttribute('aria-expanded','false');active=-1;}
function suggestions(){const q=norm(input.value);if(!q){closeSearch();return;}const ts=teams.filter(t=>norm([t.name,...t.aliases,...(t.searchAliases||[])].join(' ')).includes(q)).slice(0,5),ps=[...allPlayers.values()].filter(p=>norm(p.name+' '+(p.hof?.full||'')+' '+(p.searchText||'')).includes(q)||nickKey(p.name).includes(nickKey(input.value))).sort((a,b)=>Number(Boolean(b.hof))-Number(Boolean(a.hof))).slice(0,6);box.innerHTML=`${ps.length?`<div class="entity-result-label">JOGADORES</div>${ps.map(p=>`<button data-entity-player="${p.id}" class="entity-result"><span class="entity-avatar">${esc(p.name.slice(0,2))}</span><span><strong>${esc(p.name)}</strong><small>${p.hof?'Hall of Fame · ':''}${esc(p.teams.slice(0,2).map(t=>t.name).join(' / ')||(p.hof?'Jogador do Hall of Fame':'Jogador registrado'))}</small></span><b>↗</b></button>`).join('')}`:''}${ts.length?`<div class="entity-result-label">EQUIPES</div>${ts.map(t=>`<a href="#time/${t.id}" data-entity-team class="entity-result">${logo(t)}<span><strong>${esc(t.name)}</strong><small>${t.titles.length} títulos · ${t.members.length} jogadores</small></span><b>↗</b></a>`).join('')}`:''}${!ps.length&&!ts.length?'<p class="entity-empty">Nenhum jogador ou equipe encontrado.</p>':''}<a class="entity-all-teams" href="#times" data-entity-team>Explorar todas as equipes ↗</a>`;box.hidden=false;input.setAttribute('aria-expanded','true');active=-1;}
input.addEventListener('input',suggestions);input.addEventListener('focus',()=>{if(input.value)suggestions();});input.addEventListener('keydown',e=>{if(e.key==='Escape'){closeSearch();return;}const rows=[...box.querySelectorAll('.entity-result')];if(box.hidden||!rows.length)return;if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();active=(active+(e.key==='ArrowDown'?1:-1)+rows.length)%rows.length;rows.forEach((r,i)=>r.classList.toggle('is-keyboard-active',i===active));rows[active].scrollIntoView({block:'nearest'});}if(e.key==='Enter'){e.preventDefault();(rows[active<0?0:active]).click();}});
document.addEventListener('click',e=>{const p=e.target.closest('[data-entity-player]');if(p){showPlayer(p.dataset.entityPlayer);closeSearch();input.value='';}if(e.target.closest('[data-entity-team]')){closeSearch();input.value='';}if(!e.target.closest('.search'))closeSearch();if(e.target.closest('[data-entity-close]'))document.querySelector('#detail').close();const anchor=e.target.closest('[data-club-anchor]');if(anchor){e.preventDefault();document.getElementById(anchor.dataset.clubAnchor)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}const tr=e.target.closest('[data-club-tournament]');if(tr){const t=teams.find(t=>t.id===screen.dataset.teamId),r=t?.titles.find(r=>r.id===tr.dataset.clubTournament);if(!r)return;document.querySelector('#detail').classList.remove('profile-dialog','image-dialog');showDetail(`<span class="eyebrow">${r.year} · ${esc(t.name)}</span><h2>${esc(niceTitle(r.title))}</h2>${r.major?'<span class="club-modal-major">MAJOR CHAMPION</span>':''}<h3>Escalação registrada</h3><div class="club-modal-roster">${r.roster.length?[...new Map(r.roster.map(n=>[nickKey(n),hof(n)?.name||n])).values()].map(n=>`<span>${esc(n)}</span>`).join(''):'<p>Este registro informa o título, mas não detalha a escalação vencedora.</p>'}</div>${r.manual?`<p class="club-source-note">${esc(r.sourceNote)}</p>`:`<a class="full-link" href="#acervo/${r.source}" data-entity-close>Conferir registro original ↗</a>`}`);}});
document.addEventListener('change',e=>{if(e.target.id==='club-year'){clubYear=e.target.value;renderClub(teams.find(t=>t.id===screen.dataset.teamId));}});
document.addEventListener('input',e=>{if(e.target.id==='club-member-search'){memberQuery=e.target.value;const t=teams.find(t=>t.id===screen.dataset.teamId),list=t.members.filter(m=>(!clubYear||m.years.includes(+clubYear))&&norm(m.name).includes(norm(memberQuery)));document.querySelector('.club-members').innerHTML=list.map(memberCard).join('')||'<p class="entity-empty">Nenhum jogador encontrado.</p>';}if(e.target.id==='club-directory-search'){directoryQuery=e.target.value;const pos=e.target.selectionStart;directory();const field=document.querySelector('#club-directory-search');field.focus();field.setSelectionRange(pos,pos);}});
window.addEventListener('hashchange',closeSearch);
})();
